  } else {
    if (!o.faces) { const d = Layouts.makeDeal(spec); o.faces = d.faces; o.down = d.down; }
    addSpecials(o, spec);
    o.faces.forEach((f, i) => tiles[i].face = f);
    G.gold = new Set(o.gold || []);
