  const path = solveNow(30000);
  if (!path || !path.length) { toast('Zo gaat het niet meer lukken… probeer 🔀 Schudden'); Sound.blocked(); return; }
  G.usedHint = true; updateTools(); saveCur();
  logLvl('hint');
  // show the next one or two safe taps
