  const MS = 260;
  const flies = [tapped, y].filter(k => k >= 0).map(k => { const r = G.tiles[k].el.getBoundingClientRect(); takeOff(k); return flyTile(faceOf(k), r, to, MS); });
  renderTray(); Sound.select(); buzz(10);
