  { id: 'crown', name: 'Kroon', ok: () => S.weekWins >= 1, how: 'win een week' },
];
const frameOk = id => (FRAMES.find(f => f.id === id) || FRAMES[0]).ok();
const avatarHTML = (e, cls = 'ra') => `<span class="${cls} fr-${e.frame && e.frame !== 'none' ? e.frame : 'none'}">${e.avatar}</span>`;

const AVATARS = ['👵', '👴', '😊', '🌻', '🐱', '🐶', '🌷', '⭐', '🦋', '🍀', '🎩', '🚀'];
